//! The generated programs of the material pipeline: the backdrop passes, the material region, the glass composite and
//! the vibrant glyphs. Each is written once in WGSL (`shaders/NAME.wgsl`, with the
//! files its include lines name from `shaders/include/` and the shared module of `cupertino-gpu` ahead of it) and
//! generated by `cupertino-gpu-shaders` into GLSL ES 3.00, SPIR-V, the names its blocks and samplers are bound by,
//! and the assembled WGSL (`shaders/generated/`). The generated files are committed; a test of that crate fails when
//! they differ from a fresh generation. The compositor links the GLSL, and the headless renderer draws the same
//! programs on `cupertino-gpu`.

use cupertino_gpu::shaders::{NamedBinding, ShaderSource};

/// One generated program: its GLSL, SPIR-V and binding names, and the WGSL it was generated from.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Program {
    pub source: ShaderSource,
    /// The assembled WGSL, entry points `vs_main` and `fs_main`.
    pub wgsl: &'static str,
}

impl Program {
    /// The GLSL name of the uniform block at `group`, `binding`.
    pub fn block(&self, group: u32, binding: u32) -> Option<String> {
        self.source.bindings().into_iter().find_map(|b| match b {
            NamedBinding::Uniform {
                group: g,
                binding: n,
                block,
            } if (g, n) == (group, binding) => Some(block),
            _ => None,
        })
    }

    /// The GLSL names of the uniform block at `group`, `binding`, one per stage that reads it (each stage's GLSL
    /// names its blocks apart, and every name is bound to the same buffer).
    pub fn blocks(&self, group: u32, binding: u32) -> Vec<String> {
        self.source
            .bindings()
            .into_iter()
            .filter_map(|b| match b {
                NamedBinding::Uniform {
                    group: g,
                    binding: n,
                    block,
                } if (g, n) == (group, binding) => Some(block),
                _ => None,
            })
            .collect()
    }

    /// The GLSL name of the sampler that reads the texture at `group`, `binding`.
    pub fn sampler(&self, group: u32, binding: u32) -> Option<String> {
        self.source.bindings().into_iter().find_map(|b| match b {
            NamedBinding::Texture {
                group: g,
                binding: n,
                name,
                ..
            } if (g, n) == (group, binding) => Some(name),
            _ => None,
        })
    }
}

macro_rules! program {
    ($(#[$doc:meta])* $id:ident, $name:literal) => {
        $(#[$doc])*
        pub const $id: Program = Program {
            source: ShaderSource {
                name: $name,
                vertex_glsl: include_str!(concat!("../shaders/generated/", $name, ".vert.glsl")),
                fragment_glsl: include_str!(concat!("../shaders/generated/", $name, ".frag.glsl")),
                spirv: include_bytes!(concat!("../shaders/generated/", $name, ".spv")),
                bindings_text: include_str!(concat!("../shaders/generated/", $name, ".bindings")),
            },
            wgsl: include_str!(concat!("../shaders/generated/", $name, ".wgsl")),
        };
    };
}

/// Where every backdrop pass binds its uniform block (`PassParams`) and its source texture.
pub const PASS_BLOCK: (u32, u32) = (0, 0);
pub const PASS_SOURCE: (u32, u32) = (0, 1);

program!(
    /// One 2x box halving of the backdrop pyramid.
    DOWNSAMPLE,
    "downsample"
);
program!(
    /// One separable pass of the backdrop's Gaussian, dithered by pixel when `PassParams::flags[0]` is set.
    BLUR,
    "blur"
);
program!(
    /// The backdrop's colour filter chain.
    COLOR,
    "color"
);
program!(
    /// The source copied into the target through a bilinear sampler.
    BLIT,
    "blit"
);

/// Where the material and glass programs bind their placement block (`Placement`: the projection, the quad drawn and
/// the dither flag).
pub const PLACEMENT: (u32, u32) = (1, 0);
/// Where the material program binds its region block (`RegionParams`) and its backdrop.
pub const REGION_BLOCK: (u32, u32) = (0, 0);
pub const REGION_BACKDROP: (u32, u32) = (0, 1);
/// Where the glass program binds its container block (`GlassUniform`), its four blurred copies and its blur fill.
pub const GLASS_BLOCK: (u32, u32) = (0, 0);
pub const GLASS_LEVELS: [(u32, u32); 4] = [(0, 1), (0, 2), (0, 3), (0, 4)];
pub const GLASS_FILL: (u32, u32) = (0, 5);
/// Where the vibrant program binds its block (`VibrantUniform`), its glyphs and the copy of its target.
pub const VIBRANT_BLOCK: (u32, u32) = (0, 0);
pub const VIBRANT_GLYPHS: (u32, u32) = (0, 1);
pub const VIBRANT_BACKDROP: (u32, u32) = (0, 2);

program!(
    /// A material region: the rounded mask, the backdrop and the recipe's fill layers, dithered by pixel when
    /// `Placement::flags[0]` is set.
    MATERIAL,
    "material"
);
program!(
    /// The glass composite of one container, dithered by pixel when `Placement::flags[0]` is set.
    GLASS,
    "glass"
);
program!(
    /// Template glyphs drawn with the vibrant blend functions over a copy of the target.
    VIBRANT,
    "vibrant"
);

/// The backdrop passes, which share their block and source binding (`shaders/include/pass.wgsl`).
pub const PASSES: [Program; 4] = [DOWNSAMPLE, BLUR, COLOR, BLIT];

/// Every generated program of the crate.
pub const ALL: [Program; 7] = [DOWNSAMPLE, BLUR, COLOR, BLIT, MATERIAL, GLASS, VIBRANT];
